import { ReactNode } from "react";
import LiquidChrome from "../LiquidChrome";

function ChromeButton({ children }: { children: ReactNode }) {
  return (
    <button className="relative py-4 px-6 rounded-md bg-neutral-950 overflow-hidden group text-white font-bold tracking-widest drop-shadow-md">
      <div className="absolute inset-0 z-0 opacity-80 group-hover:opacity-100 transition-opacity duration-500">
        <LiquidChrome
          baseColor={[0.1, 0.1, 0.1]}
          speed={1}
          amplitude={0.6}
          interactive={true}
        />
      </div>
      <span className="relative z-10">{children}</span>
    </button>
  );
}

export default ChromeButton;
